INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('chocolate-truffle', 'chocolate-truffle-cake', 'Chocolate Truffle Birthday Cake', 'চকলেট ট্রাফল জন্মদিনের কেক', 'birthday', '/images/cake-chocolate-truffle.webp', 850, 950, 4.9, 128, 'Best Seller', 'চকলেট প্রেমীদের প্রথম পছন্দ', 'বেলজিয়ান কোকো দিয়ে তৈরি নরম চকলেট স্পঞ্জ, ভেতরে ডার্ক চকলেট ট্রাফল ক্রিম আর উপরে গ্লসি গানাশ ড্রিপ ও চকলেট কার্ল। প্রতিটি অর্ডার ফ্রেশ বেক করা হয়।', 1, 0, 0);
INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('red-velvet', 'red-velvet-cream-cheese-cake', 'Red Velvet Cream Cheese Cake', 'রেড ভেলভেট ক্রিম চিজ কেক', 'birthday', '/images/cake-red-velvet.webp', 980, 1150, 4.8, 96, NULL, 'ভ্যালেন্টাইন ও অ্যানিভার্সারির জন্য', 'ক্লাসিক রেড ভেলভেট স্পঞ্জের সাথে ঘরে বানানো ক্রিম চিজ ফ্রস্টিং। হালকা মিষ্টি, তুলতুলে আর দেখতে দারুণ আকর্ষণীয়।', 1, 0, 1);
INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('strawberry-cream', 'fresh-strawberry-cream-cake', 'Fresh Strawberry Cream Cake', 'ফ্রেশ স্ট্রবেরি ক্রিম কেক', 'birthday', '/images/cake-strawberry-cream.webp', 900, 1050, 4.7, 74, NULL, 'তাজা স্ট্রবেরি দিয়ে সাজানো', 'তাজা স্ট্রবেরি আর হুইপড ক্রিমের হালকা কেক। ফ্রেশ ফলের মিষ্টি গন্ধ আর নরম স্পঞ্জ — গ্রীষ্মের দুপুরের জন্য পারফেক্ট।', 1, 0, 2);
INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('rainbow-birthday', 'vanilla-rainbow-birthday-cake', 'Vanilla Rainbow Birthday Cake', 'ভ্যানিলা রেইনবো জন্মদিনের কেক', 'birthday', '/images/cake-rainbow-birthday.webp', 1050, 1200, 4.9, 152, 'Popular', 'পার্টির সেন্টারপিস', 'ছয় স্তরের রঙিন ভ্যানিলা স্পঞ্জ, প্যাস্টেল বাটারক্রিম রোজেট আর স্প্রিংকলস। বাচ্চাদের পার্টির সেন্টারপিস।', 1, 0, 3);
