INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('custom-theme', 'custom-theme-cake', 'Custom Theme Cake', 'কাস্টম থিম কেক', 'custom', '/images/cake-custom-theme.webp', 2400, 2800, 4.9, 43, 'Made to Order', 'আপনার কল্পনার কেক', 'যেকোনো থিম, রঙ বা ক্যারেক্টারে কেক ডিজাইন করিয়ে নিন। অর্ডারের পর আমাদের টিম আপনার সাথে ডিজাইন কনফার্ম করবে।', 1, 0, 9);
INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('cupcakes', 'nutella-cupcakes-box-of-6', 'Nutella Cupcakes (Box of 6)', 'নুটেলা কাপকেক (৬ পিস)', 'cupcakes', '/images/cake-cupcakes.webp', 450, 550, 4.8, 112, 'Best Seller', 'অফিস পার্টির জন্য', 'ভেতরে নুটেলা ফিলিং, উপরে চকলেট সুইস মেরিংগি ফ্রস্টিং আর স্প্রিংকলস। ছয়টি কাপকেকের বক্স।', 1, 0, 10);
