INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('mango-mousse', 'mango-mousse-cake', 'Mango Mousse Cake', 'ম্যাংগো মুস কেক', 'cheesecakes', '/images/cake-mango-mousse.webp', 950, 1100, 4.7, 61, NULL, 'মৌসুমি আমের স্বাদ', 'মিষ্টি আমের মুস, ভ্যানিলা স্পঞ্জ আর গ্লসি আমের গ্লেজ। হালকা, ঠান্ডা আর ফ্রেশ।', 1, 0, 12);
INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('macarons', 'assorted-macaron-gift-box-12', 'Assorted Macaron Gift Box (12 pcs)', 'অ্যাসোর্টেড ম্যাকারন গিফট বক্স', 'gift', '/images/cake-macarons.webp', 1050, 1250, 4.8, 47, 'Gift Ready', 'গিফট র্যাপিং ফ্রি', 'প্যাস্টেল রঙের ১২টি ম্যাকারন — ভ্যানিলা, রোজ, পিস্তা, ল্যাভেন্ডার ও চকলেট। সুন্দর গিফট বক্সে।', 1, 0, 13);
