INSERT INTO products (id, slug, name, bn, category, image, price, old_price, rating, reviews, badge, tag, description, sizes, out_of_stock, sort) VALUES ('lotus-cheesecake', 'lotus-biscoff-cheesecake', 'Lotus Biscoff Cheesecake', 'লোটাস বিসকফ চিজকেক', 'cheesecakes', '/images/cake-cheesecake.webp', 1250, 1400, 4.9, 71, NULL, 'আবার স্টকে আসছে', 'লোটাস বিসকফ স্প্রেড আর ক্রাশ করা বিস্কুট দিয়ে তৈরি নো-বেক চিজকেক।', 1, 1, 15);
INSERT INTO banners (id, eyebrow, title, highlight, description, image, primary_label, primary_to, secondary_label, secondary_to, show_stats, active, sort) VALUES ('banner-signature', 'ঢাকার ফ্রেশ বেকারি · ২০১৯ থেকে', 'প্রতিটি আনন্দের মুহূর্তে', 'তাজা কেক', 'জন্মদিন, অ্যানিভার্সারি কিংবা হঠাৎ মন ভালো হওয়ার দিন — CakeHaus-এর হাতে বানানো কেক পৌঁছে যাবে মাত্র ২ ঘণ্টায়।', '/images/hero-cakes.webp', 'কেক অর্ডার করুন', '/shop', 'ওয়েডিং কেক', '/shop?cat=wedding', 1, 1, 0);
INSERT INTO banners (id, eyebrow, title, highlight, description, image, primary_label, primary_to, secondary_label, secondary_to, show_stats, active, sort) VALUES ('banner-wedding', 'ওয়েডিং সিজন · কাস্টম ডিজাইন', 'আপনার বড় দিনে', 'রাজকীয় কেক', 'মাল্টি-টায়ার ওয়েডিং কেক, ফ্রেশ ফুলের সাজ আর নিজের পছন্দের ডিজাইন — বেকার সাথে কথা বলে বানিয়ে নিন।', '/images/cake-wedding-tier.webp', 'ওয়েডিং কেক দেখুন', '/shop?cat=wedding', 'কাস্টম ডিজাইন', '/shop?cat=custom', 1, 1, 1);
INSERT INTO banners (id, eyebrow, title, highlight, description, image, primary_label, primary_to, secondary_label, secondary_to, show_stats, active, sort) VALUES ('banner-birthday', 'জন্মদিন স্পেশাল · ১০% ছাড়', 'জন্মদিনটা হোক', 'আরও মিষ্টি', 'HBD10 কোডে জন্মদিনের প্রতিটি কেকে ১০% ছাড়। অর্ডার করুন — ২ ঘণ্টায় কেক পৌঁছে যাবে দরজায়।', '/images/hero-birthday.webp', 'অফার নিন', '/shop?cat=birthday', 'সব কেক', '/shop', 1, 1, 2);
